function ($rootScope, $scope, snRecordWatcher, spUtil, $location, $uibModal, cabrillo, $timeout, $http, spModal) {
	$scope.userID = $scope.user.sys_id;

	if($location.search().internal_view == "true"){
		$("header").css("display","none");
		$("footer").css("display","none");
	}
	if (cabrillo.isNative())
		$scope.isViewNative = true;
	$scope.$on('sp_loading_indicator', function(e, value) {
		$scope.isLoading = value;
	});
	$scope.openPopUp = function() {
		var url = "$chat_support.do?queueID=" + $scope.data.connect_support_queue_id;
		var popup = window.open (url, "popup", "width=900, height=600"); 
	};
	$scope.openLogin = function () {
		$location.search('id=ibfs_sso_redirect');
		$scope.modalInstance = $uibModal.open({
			templateUrl: 'modalLogin',
			scope: $scope
		});
	};
	$rootScope.$on('sp.avatar_changed', function() {
		$scope.userID = "";
		$timeout(function(){
			$scope.userID = $scope.user.sys_id;
		});
	});
	$scope.isHomepage = function() {
		if (!$scope.page.id)
			return true;
		if ($scope.page.id == $scope.portal.homepage_dv)
			return true;
		return false;
	};
	$scope.openImpersonationWindow = function(){
		spModal.prompt('UserID to impersonate?',this.impersonatingUserID).then(function (answer) {
            $scope.impersonate(answer);
        });
	};
	$scope.impersonate = function(user_name) {
		if (!user_name)
			return;

$http.post('/api/now/ui/impersonate/' + user_name, {}).success(function() {
			$scope.show_error = false;
			location.reload();
		}).error(function(response) {
             if (response.error) {
				 $scope.show_error = true;
				 $scope.error = response.error;
				 console.error("Impersonate failed", response.error);
			 }
		});
	};
}

