api.controller = function ($q, $scope, $rootScope, $log, $location, spUtil, amb, $http, spAriaUtil, $timeout, spNavStateManager, $interval, $sce) {
    var c = this;
    var ajaxCall;
    c.showFilter = false;
    c.filters = [];
    c.filterCount = 0;
    c.OG_DATA = [];
    c.PAGED_DATA = [];
    c.data.list = [];
    c.data.p = 0;
    c.data.window_size = 20;
    c.data.num_pages = 0;
    c.data.window_start = 0;
    c.data.window_end = 20;
    c.data.row_count = 0;
    c.data.o = "number";
    c.data.d = "desc";
    c.hasFilter = false;
    c.rowsRemoved = 0;
    c.fileServicePromise = undefined;
    c.ifOnlyOneFilter = function () {
        return c.filters.length == 1;
    };
    c.restoreData = function () {
        c.data.list = c.OG_DATA;
        c.hasFilter = false;
        c.resetFilter();
    };
    c.runFilter = function () {
        var i = 0;
        if (c.OG_DATA.length == 0) {
            c.OG_DATA = c.data.list.slice(0);
        }
        c.data.list = c.OG_DATA.slice(0);
        c.data.list = c.data.list.filter(function (obj) {
            var ands = [];
            var ors = [];
            var result = true;
            var bool = "AND";
            var filterValue;
            var currValue;
            var exclude = false;
            for (i = 0; i < c.filters.length; ++i) {
                exclude = false;
                if (c.filters[i].isLogic) {
                    bool = c.filters[i].logic;
                    continue;
                }
                filterValue = c.filters[i].value.toString().toUpperCase().trim();
                currValue = obj[c.filters[i].name].display_value.toString().toUpperCase().trim();
                if (filterValue[0] === "!") {
                    exclude = true;
                    filterValue = filterValue.substr(1);
                }
                if (bool == "AND") {
                    result = currValue == filterValue;
                    result = result || currValue.startsWith(filterValue);
                    if (exclude) {
                        result = !result;
                    }
                    ands.push(result);
                }
                else {
                    result = currValue == filterValue;
                    result = result || currValue.startsWith(filterValue);
                    bool = "AND";
                    if (exclude) {
                        result = !result;
                    }
                    ors.push(result);
                }
            }
            result = ands.every(function (x) {
                return x;
            });
            result = result || ors.some(function (x) {
                return x;
            })
            return result;
        });
        c.hasFilter = true;
    };
    c.datePicker = function () {
        $('#datetimepicker1').datetimepicker();
    }
    c.toggleFilter = function () {
        c.showFilter = !c.showFilter;
        if (c.showFilter && c.filters.length == 0) {
            c.incFilterCount();
        }
    }
    c.resetFilter = function () {
        c.filters = [];
        c.incFilterCount();
    };
    c.incFilterCount = function () {
        c.filters.push({
            label: "",
            name: c.data.filters.fields[0].name,
            type: "",
            value: ""
        });
        c.filterCount = c.filterCount + 1;
        return;
    }
    c.decFilterCount = function () {
        if (c.filterCount <= 0) {
            c.filterCount = 0;
        }
        else {
            c.filterCount = c.filterCount - 1;
            c.filters.pop();
        }
        return;
    };
    c.removeSpecificFilter = function (i) {
        if (i < 0) {
            return;
        }
        if (i == c.filters.length - 1) {
            c.filters.splice(i, 1);
            c.filterCount = c.filterCount - 1;
            if (i > 0 && c.filters[i - 1].isLogic) {
                c.removeSpecificFilter(i - 1);
            }
            return;
        }
        c.filters.splice(i, 1);
        c.filterCount = c.filterCount - 1;
        if (c.filters[0].isLogic) {
            c.removeSpecificFilter(0);
        }
        if (c.filters.length >= i && i >= 1 && c.filters[i].isLogic && c.filters[i - 1].isLogic) {
            c.removeSpecificFilter(i - 1);
        }
    };
    c.getFilterCount = function () {
        return new Array(c.filterCount);
    };
    c.addAND = function () {
        c.filters.push({
            isLogic: true,
            logic: "AND"
        });
        c.filters.push({
            label: "",
            name: c.data.filters.fields[0].name,
            type: "",
            value: ""
        });
        c.filterCount = c.filterCount + 2;
    };
    c.addOR = function () {
        c.filters.push({
            isLogic: true,
            logic: "OR"
        });
        c.filters.push({
            label: "",
            name: c.data.filters.fields[0].name,
            type: "",
            value: ""
        });
        c.filterCount = c.filterCount + 2;
    };
    c.removeOR = function (i) {
        c.removeSpecificFilter(i);
    };
    $scope.$on("data_table.click", function (e, params) {
        var url;
        switch (params.record.targetTable) {
            case "x_fmc_ibfs_pleadings_and_comments":
                url = e.targetScope.widget_parameters.url.replace("<number>", params.record.number.display_value);
                break;
            case "u_frn":
                url = e.targetScope.widget_parameters.url.replace("<number>", params.record.u_frn.display_value);
                break;
            default:
                url = e.targetScope.widget_parameters.url.replace("<number>", params.record.number.display_value);
        }
        $location.url(url);
    });
    $scope.printTable = function () {
        $rootScope.$broadcast("advSearch.preparingPrint", { preparingPrint: true, dataTableWidgetType: "custom" });
$scope.data.printMode = true;
c.data.listBackup = copyJSON(c.data.list);
c.data.list = c.data.all_data;
        $rootScope.$broadcast("advSearch.togglePrintMode", { printMode: true });
    }
    $rootScope.$on("advSearch.noPrintElementsAreHidden", function (event, data) {
        if (data.dataTableWidgetType != "custom") return;
        $timeout(function () {
            $rootScope.$broadcast("advSearch.preparingPrint", { preparingPrint: false });
            $timeout(function () {
                window.print();
                $rootScope.$broadcast("advSearch.togglePrintMode", { printMode: false });
                $scope.data.printMode = false;
c.data.list = c.data.listBackup;
            }, 200);
        }, 200)
    });
    $scope.$watch(function () { return c.data.all_data }, function (newValue, oldValue) {
        var i, j, k;
        var size;
        var page_data = [];
        if (newValue != undefined) {
            c.PAGED_DATA = [];
            c.data.p = 0;
            c.data.window_size = 20;
c.data.num_pages = Math.ceil(newValue.length / c.data.window_size);
            c.data.window_start = c.data.p * c.data.window_size;
            c.data.window_end = (c.data.p + 1) * c.data.window_size;
            c.data.row_count = newValue.length;
            if (c.data.row_count == 0) {
                c.data.row_count = undefined;
            }
            for (i = 0; i < c.data.num_pages; ++i) {
                page_data = newValue.slice(i * c.data.window_size, i * c.data.window_size + c.data.window_size);
                c.PAGED_DATA.push(page_data);
            }
            c.data.list = c.PAGED_DATA[0].slice(0);
            c.updateFileServiceLink();
        }
    });
    c.updateFileServiceLink = function () {
        var item, link;
        if (angular.isDefined(c.fileServicePromise)) {
            return;
        }
        c.fileServicePromise = $interval(function () {
            var key, i, j;
            var links = [];
            for (i = 0; i < c.data.list.length; ++i) {
                item = c.data.list[i];
                if (item.hasOwnProperty("requiresWatch") && item.requiresWatch == true) {
                    for (j = 0; j < item[item.watchField].links.length; ++j) {
                        link = item[item.watchField].links[j];
                        if (link.hasOwnProperty('isProcessed') && !link.isProcessed) {
                            links.push({
                                linkIndex: j,
                                isProcessed: false,
                                attachment_name: link.attachment_name,
                                table_name: link.table_name,
                                record_sys_id: link.record_sys_id
                            });
                        }
                    }
                }
            }
            if (links.length > 0) {
                c.server.get({
                    updateFileServiceLinks: true,
                    fileServiceLinks: links
                }).then(function (resp) {
                    for (i = 0; i < resp.data.fileServiceLinks.length; ++i) {
                        link = resp.data.fileServiceLinks[i];
                        for (j = 0; j < c.data.list.length; ++j) {
                            if (c.data.list[j].hasOwnProperty("watchField")) {
                                item = c.data.list[j][c.data.list[j].watchField];
                                if (item.hasOwnProperty("links") &&
                                    item.links.length > link.linkIndex &&
                                    item.links[link.linkIndex].attachment_name == link.attachment_name &&
                                    item.links[link.linkIndex].table_name == link.table_name &&
                                    item.links[link.linkIndex].record_sys_id == link.record_sys_id) {
                                    if (link.hasOwnProperty("isProcessed") && link.isProcessed) {
                                        item.links[link.linkIndex].url = link.link;
                                        item.links[link.linkIndex].isProcessed = link.isProcessed;
                                    }
                                }
                            }
                        }
                    }
                });
            }
        }, 10000);
    };
    $timeout(c.stopFileServiceLinkUpdates, 1200000);
    c.stopFileServiceLinkUpdates = function () {
        if (angular.isDefined(c.fileServicePromise)) {
            $interval.cancel(c.fileServicePromise);
            c.fileServicePromise = undefined;
        }
    };
    $scope.exportTypes = [
        { label: 'Excel', value: 'EXCEL' },
        { label: 'CSV', value: 'CSV' }
    ];
    var keys = ['table', 'filter', 'p', 'o', 'd'];
    var eventNames = {
        click: 'data_table.click',
        setFilter: 'data_table.setFilter',
        setKeywords: 'data_table.setKeywords'
    };
    $scope.go = function (table, item) {
        if ($scope.options.rowsNotClickable) return;
        spNavStateManager.onRecordChange(table).then(function () {
            var parms = {};
            parms.table = table;
            parms.sys_id = item.sys_id;
            parms.record = item;
            $scope.ignoreLocationChange = true;
            for (var x in c.data.list) {
                c.data.list[x].selected = false;
            }
            item.selected = true;
            $scope.$emit(eventNames.click, parms);
        }, function () {
        });
    };
    function recoverStateFromUrl() {
        $scope.data.fields = [];
        var s = $location.search();
        for (var x in keys) {
            if (s[keys[x]]) {
                $scope.data[keys[x]] = s[keys[x]];
            }
        }
        $scope.server.update().then(function (data) {
            if (s.sys_id) {
                for (var x in data.list) {
                    if (data.list[x].sys_id == s.sys_id) {
                        $scope.go(s.table, data.list[x]);
                    }
                }
            }
        });
    }
    $scope.getNumber = function (num) {
        return new Array(num);
    }
    $scope.mathMin = function (v1, v2) {
        return Math.min(v1, v2);
    }
    $scope.setPageNum = function (num) {
        if (num == c.data.p) {
            return;
        }
        c.data.p = num;
        c.data.list = c.PAGED_DATA[c.data.p].slice(0);
        c.data.window_start = c.data.p * c.data.window_size;
        c.data.window_end = c.data.window_start + c.PAGED_DATA[c.data.p].length;
    }
    $scope.setOrderBy = function (field) {
        var d = "desc";
        if (c.data.o == field) {
            if (c.data.d == "asc")
                d = "desc";
            else
                d = "asc";
        }
        c.data.o = field;
        c.data.d = d;
        c.data.all_data = c.data.all_data.slice(0).sort(c.sortFunction(field, d));
    }
    c.sortFunction = function (key, order) {
        return function innerSort(a, b) {
            if (!a.hasOwnProperty(key) || !b.hasOwnProperty(key)) {
                return 0;
            }
            var valueA = (a[key].display_value).toUpperCase();
            var valueB = (b[key].display_value).toUpperCase();
            var comparison = 0;
            if (valueA > valueB) {
                comparison = 1;
            } else if (valueA < valueB) {
                comparison = -1;
            }
            return (
                (order == 'asc') ? (comparison * -1) : comparison
            );
        };
    }
    $scope.rowsWerePruned = function () {
        if (!$scope.data.list)
            return;
        if (c.hasFilter)
            return;
        $scope.rowsPruned = $scope.mathMin($scope.data.window_end, $scope.data.row_count) - $scope.data.window_start - $scope.data.list.length;
        return $scope.rowsPruned > 0;
    }
    $scope.rowsWereFiltered = function () {
        if (!$scope.data.list)
            return;
        if (!c.hasFilter)
            return;
        c.rowsRemoved = $scope.mathMin($scope.data.window_end, $scope.data.row_count) - $scope.data.window_start - $scope.data.list.length;
        return c.rowsRemoved > 0;
    }
    $scope.showFilter = function () {
        return !$scope.data.list.length && !$scope.data.num_pages && !$scope.data.invalid_table && !$scope.loadingData;
    }
    c.createQueryTerm = function (table, field, sys_id, operator) {
        var selected = {};
        var valid = false;
        for (var i = 0; i < c.data.all_data.length; ++i) {
            if (c.data.all_data[i].sys_id == sys_id) {
                selected = c.data.all_data[i];
            }
        }
        var display_value, value, label;
        if (selected.hasOwnProperty(field)) {
            display_value = selected[field].display_value;
            value = selected[field].value;
            label = selected[field].label;
            valid = true;
        }
        return $q(function (resolve, reject) {
            if (valid) {
                resolve({
                    displayValue: display_value,
                    field: field,
                    query_term_field: field,
                    label: label,
                    type: "string",
                    value: value,
                    operator: operator
                });
            }
            else {
                reject("Unable to run operation on selected record");
            }
        }).then(function (selection) {
            return selection;
        }, function (errorMsg) {
            spUtil.addErrorMessage(errorMsg);
        })
    };
    c.showMatching = function (field, newTerm) {
        c.filters.push({
            label: newTerm.label,
            name: field,
            type: newTerm.type,
            value: newTerm.displayValue
        });
        c.runFilter();
    };
    c.filterOut = function (field, newTerm) {
        c.filters.push({
            label: newTerm.label,
            name: field,
            type: newTerm.type,
            value: "!" + newTerm.displayValue
        });
        c.runFilter();
    };
    function isSameField(t1, t2) {
        if ('left' in t1 && 'left' in t2)
            return t1.left.query_term_field === t2.left.query_term_field;
        else if ('left' in t1)
            return t1.left.query_term_field === t2.query_term_field;
        else if ('left' in t2)
            return t1.query_term_field === t2.left.query_term_field;
        return t1.query_term_field === t2.query_term_field;
    }
    function copyJSON(item) {
        return JSON.parse(JSON.stringify(item));
    }
    $scope.trustAsHtml = function (string) {
        return $sce.trustAsHtml(string);
    };
    $scope.logScope = function () {
        console.log("scope = ", $scope);
    }
    $scope.handleActiveElement = function (event) {
        if (event.key == "Tab" && !event.shiftKey) {
            var elt = document.getElementById("advSearch_personalizeColsBtn");
            if (elt) {
                event.preventDefault();
                elt.focus();
            }
        }
    }
}

